//! Current proof-attachment payloads for both explicit Norito length layouts.

use iroha_crypto::{Hash, HashOf, LaneCommitmentId, MerkleProof};
use iroha_data_model::{
    nexus::{LanePrivacyMerkleWitness, LanePrivacyProof, LanePrivacyWitness},
    proof::{ProofAttachment, ProofBox, VerifyingKeyId},
};
use norito::{SerializePayload, core as ncore};

/// Print sixteen flags/mask/payload rows generated by the current Rust codec.
pub fn emit() {
    for row in rows() {
        println!("{row}");
    }
}

fn rows() -> Vec<String> {
    let mut rows = Vec::new();
    for flags in [0, ncore::header_flags::COMPACT_LEN] {
        let _layout = ncore::DecodeFlagsGuard::enter(flags);
        for mask in 0_u8..8 {
            let mut value = ProofAttachment::new_ref(
                "pipa-r/pasta".into(),
                ProofBox::new("pipa-r/pasta".into(), vec![1, 2]),
                VerifyingKeyId::new("pipa-r/pasta", "vk_transfer"),
            );
            value.vk_commitment = (mask & 1 != 0).then_some([0x55; 32]);
            value.envelope_hash = (mask & 2 != 0).then(|| Hash::new([1, 2]).into());
            value.lane_privacy = (mask & 4 != 0).then(|| LanePrivacyProof {
                commitment_id: LaneCommitmentId::new(7),
                witness: LanePrivacyWitness::Merkle(LanePrivacyMerkleWitness {
                    leaf: [0xaa; 32],
                    proof: MerkleProof::from_audit_path(
                        1,
                        [0x22, 0x44]
                            .map(|seed| {
                                Some(HashOf::from_untyped_unchecked(Hash::prehashed([seed; 32])))
                            })
                            .to_vec(),
                    ),
                }),
            });
            let mut payload = Vec::new();
            value
                .serialize(&mut ncore::Encoder::for_buffer(&mut payload))
                .expect("encode proof-attachment fixture");
            let (decoded, used) =
                <ProofAttachment as ncore::DecodeFromSlice>::decode_from_slice(&payload)
                    .expect("decode proof-attachment fixture");
            assert_eq!(used, payload.len());
            assert_eq!(decoded, value);
            rows.push(format!("{flags}\t{mask}\t{}", hex::encode(payload)));
        }
    }
    rows
}

#[cfg(test)]
mod tests {
    use super::rows;

    #[test]
    fn every_tail_and_length_layout_roundtrips() {
        let rows = rows();
        assert_eq!(rows.len(), 16);
        let selectors: std::collections::BTreeSet<_> = rows
            .iter()
            .map(|row| row.rsplit_once('\t').expect("payload column").0)
            .collect();
        assert_eq!(selectors.len(), 16);
    }
}
